    receiveWorkosWebhook: {
        parameters: {
            query?: never;
            header: {
                /** @description `t=<milliseconds since epoch>, v1=<hex HMAC-SHA256>` */
                "WorkOS-Signature": string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["WorkosWebhookEvent"];
            };
        };
        responses: {
            /** @description The event is saved. Processing happens later. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data: components["schemas"]["WorkosWebhookReceipt"];
                    };
                };
            };
            /** @description `invalid_signature` for a missing, malformed, mismatched, or expired signature. `bad_request` for a signed body that is not a WorkOS event. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WorkosWebhookErrorResponse"];
                };
            };
            /** @description `payload_too_large`: the body is larger than 1 MB. */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WorkosWebhookErrorResponse"];
                };
            };
            /** @description `internal_error`: an unexpected server failure. WorkOS retries the delivery. */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WorkosWebhookErrorResponse"];
                };
            };
            /** @description `webhook_not_configured`: no webhook secret, or WorkOS is not verified in production. `database_unavailable`: the ledger cannot be reached. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WorkosWebhookErrorResponse"];
                };
            };
        };
    };
